import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const c="/ascendc.github.io/assets/tailcore_tiling.C0UZpSIQ.png",m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子实现","link":"/guide/operator_practice/simd_operator_impl/simd_operator_impl"},{"text":"矢量编程","link":"/guide/operator_practice/simd_operator_impl/vector_programming/vector_programming"},{"text":"多核Tiling切分","link":"/guide/operator_practice/simd_operator_impl/vector_programming/multi_core_tiling/overview"},{"text":"尾核切分","link":"/guide/operator_practice/simd_operator_impl/vector_programming/multi_core_tiling/tail_core_split"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_impl/vector_programming/multi_core_tiling/tail_core_split.md","filePath":"guide/operator_practice/simd_operator_impl/vector_programming/multi_core_tiling/tail_core_split.md","outlineHeaders":[{"level":2,"title":"Tiling实现","slug":"Tiling实现","link":"#Tiling实现"},{"level":2,"title":"算子类实现","slug":"算子类实现","link":"#算子类实现"}],"lastUpdated":1787050286000}'),e={name:"guide/operator_practice/simd_operator_impl/vector_programming/multi_core_tiling/tail_core_split.md"};function t(i,s,o,r,d,h){return n(),p("div",null,[...s[0]||(s[0]=[l('<div><article class="markdown-body"><h1>尾核切分</h1><p>在实际算子开发中，受输入数据总量与切分单位的制约，并非所有场景都能将计算完全均匀地分配到每个核上。该场景中，主块均分后存在剩余数据<code>mainTileRemainder</code>，但剩余数据无法以DataBlock为最小单位均匀分配到每个核（<code>tailBlockNumEachCore</code>为0，<code>remainingTailLength</code>不为0），只能继续分配给部分核。获得额外DataBlock的核为整核，其余为尾核；此时核间负载不均衡，需要分别处理整核和尾核。由于<code>tailBlockNumEachCore</code>为0，各核未分配到基础尾块，因此尾核内只包含主块，整核比尾核多处理一个DataBlock的尾块。数据切分后，前<code>formerNum</code>个核为整核，各处理<code>formerLength</code>个元素（含主块和尾块）；其余核为尾核，各处理<code>tailLength</code>个元素（仅含主块）。</p><p>本场景样例的完整代码请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/02_features/02_tiling_selector/vector_tiling_strategy/README.md#scenario2-main-tile-tail-core">场景2：尾核切分</a>。样例中固定使用8个核，主块长度<code>mainTileLength</code>为3200个<code>half</code>元素，数据整体长度为256064个<code>half</code>元素。数据按DataBlock对齐后，前4个核各处理32016个元素，后4个核各处理32000个元素；整核包含10个主块和16个元素的尾块，尾核只包含10个主块。数据切分示意如下图所示。</p><p><strong>图 1</strong> 数据切分示意图</p><p><img src="'+c+`" alt="数据切分示意图" title="数据切分示意图"></p><p>本场景中整核和尾核处理的元素数量、主块数量及尾块情况不同，无法仅用一组<code>blockLength</code>、<code>tileNum</code>和<code>lastTileLength</code>描述所有核。因此Tiling参数新增<code>formerNum</code>记录整核数量，并分别使用<code>former*</code>和<code>tail*</code>参数描述记录整核和尾核相关Tiling信息的参数；由于尾核内只包含主块，无需定义<code>tailLastTileLength</code>。Tiling结构体包含以下成员：</p><ul><li>formerNum：分配到数据量较多的核数，即整核的核数。</li><li>formerLength：整核计算的元素数量。</li><li>formerTileNum：整核中主块的数量。</li><li>formerLastTileLength：整核中尾块的元素数量。</li><li>tailLength：尾核计算的元素数量。</li><li>tailTileNum：尾核中主块的数量。</li></ul><h2 id="Tiling实现">Tiling实现<a class="header-anchor" href="#Tiling实现">​</a></h2><p>Tiling结构体定义如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">struct</span><span class="w"> </span><span class="nc">MainTileWithTailCoreTiling</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">formerNum</span><span class="p">;</span><span class="w">            </span><span class="c1">// 整核数量</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">formerLength</span><span class="p">;</span><span class="w">         </span><span class="c1">// 整核处理的元素数量</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">formerTileNum</span><span class="p">;</span><span class="w">        </span><span class="c1">// 整核中主块的数量</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">formerLastTileLength</span><span class="p">;</span><span class="w"> </span><span class="c1">// 整核中尾块的元素数量</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">tailLength</span><span class="p">;</span><span class="w">           </span><span class="c1">// 尾核处理的元素数量</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">tailTileNum</span><span class="p">;</span><span class="w">          </span><span class="c1">// 尾核中主块的数量</span>
<span class="p">};</span>
</code></pre></div><p>Host侧Tiling沿用<a href="tail_block_even_split.html">尾块均分</a>中的DataBlock对齐、主块分配和基础尾块计算，得到：按DataBlock均分后仍无法均分到每个核的剩余元素数量<code>remainingTailLength</code>、每个核分配到的DataBlock数量<code>tailBlockNumEachCore</code>、每个核基础尾块的元素数量<code>baseLastTileLength</code>、每个核已分配的基础元素数量<code>baseLength</code>，以及对应的主块数量<code>baseTileNum</code>。当<code>remainingTailLength</code>不为0时，尾块均分分支不成立，继续执行以下步骤：</p><ol><li><p><code>remainingTailLength</code>对应的剩余数据无法均分到每个核，只能分配给前<code>formerNum</code>个整核。用<code>remainingTailLength</code>除以<code>alignNum</code>得到整核数量<code>formerNum</code>；整核比尾核多处理一个DataBlock（含<code>alignNum</code>个<code>half</code>元素），因此<code>formerLength</code>由<code>baseLength</code>加上<code>alignNum</code>得到，而<code>tailLength</code>直接取<code>baseLength</code>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">remainingTailLength</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">0U</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="p">...</span>
<span class="w">    </span><span class="k">return</span><span class="p">;</span>
<span class="p">}</span>

<span class="kt">uint32_t</span><span class="w"> </span><span class="n">formerNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">remainingTailLength</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">alignNum</span><span class="p">;</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">formerLength</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">baseLength</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">alignNum</span><span class="p">;</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">tailLength</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">baseLength</span><span class="p">;</span>
</code></pre></div></li><li><p>整核和尾核的主块数量相同，均等于<code>baseTileNum</code>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">uint32_t</span><span class="w"> </span><span class="n">formerTileNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">baseTileNum</span><span class="p">;</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">tailTileNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">baseTileNum</span><span class="p">;</span>
</code></pre></div></li><li><p>进一步判断<code>tailBlockNumEachCore</code>是否为0。等于0表示各核未分配到基础尾块（<code>baseLastTileLength</code>为0），因此尾核内只包含主块；整核比尾核多处理一个DataBlock，因此整核尾块长度<code>formerLastTileLength</code>直接设置为<code>alignNum</code>。此时进入尾核切分场景，使用<code>MainTileWithTailCoreTiling</code>结构体传递Tiling切分信息。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">tailBlockNumEachCore</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">0U</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">formerLastTileLength</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">alignNum</span><span class="p">;</span>
<span class="w">    </span><span class="n">MainTileWithTailCoreTiling</span><span class="w"> </span><span class="n">tiling</span><span class="p">{</span>
<span class="w">        </span><span class="n">formerNum</span><span class="p">,</span><span class="w"> </span><span class="n">formerLength</span><span class="p">,</span><span class="w"> </span><span class="n">formerTileNum</span><span class="p">,</span><span class="w"> </span><span class="n">formerLastTileLength</span><span class="p">,</span><span class="w"> </span><span class="n">tailLength</span><span class="p">,</span><span class="w"> </span><span class="n">tailTileNum</span><span class="p">};</span>
<span class="w">    </span><span class="n">add_custom</span><span class="o">&lt;</span><span class="n">MainTileWithTailCoreTiling</span><span class="o">&gt;&lt;&lt;&lt;</span><span class="n">numBlocks</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(</span><span class="n">xDevice</span><span class="p">,</span><span class="w"> </span><span class="n">yDevice</span><span class="p">,</span><span class="w"> </span><span class="n">zDevice</span><span class="p">,</span><span class="w"> </span><span class="n">tiling</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div></li></ol><p>对形状为<code>(1, 256064)</code>的输入数据计算后，Tiling结构体内各个变量的值如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">MainTileWithTailCoreTiling</span><span class="w"> </span><span class="n">tiling</span><span class="p">{</span>
<span class="w">    </span><span class="mi">4</span><span class="p">,</span><span class="w">     </span><span class="c1">// formerNum：前4个核为整核</span>
<span class="w">    </span><span class="mi">32016</span><span class="p">,</span><span class="w"> </span><span class="c1">// formerLength：整核计算32016个half</span>
<span class="w">    </span><span class="mi">10</span><span class="p">,</span><span class="w">    </span><span class="c1">// formerTileNum：整核包含10个主块</span>
<span class="w">    </span><span class="mi">16</span><span class="p">,</span><span class="w">    </span><span class="c1">// formerLastTileLength：整核包含16个half的尾块</span>
<span class="w">    </span><span class="mi">32000</span><span class="p">,</span><span class="w"> </span><span class="c1">// tailLength：尾核计算32000个half</span>
<span class="w">    </span><span class="mi">10</span><span class="w">     </span><span class="c1">// tailTileNum：尾核包含10个主块</span>
<span class="p">};</span>
</code></pre></div><h2 id="算子类实现">算子类实现<a class="header-anchor" href="#算子类实现">​</a></h2><p>核函数（Kernel）侧算子仍采用<a href="../../../../programming_guide/programming_model/ai_core_simd_programming/cpp_tensor_programming/static_tensor_programming.html">静态Tensor编程</a>方式实现。与<a href="tail_block_even_split.html">尾块均分</a>相比，本场景中整核和尾核处理的数据长度不同，因此<code>Init</code>函数需要根据<code>GetBlockIdx()</code>判断当前核是整核还是尾核，并分别设置Global Memory偏移和循环参数。<code>blockIdx</code>表示当前逻辑核的索引。</p><p>整核使用<code>formerLength</code>、<code>formerTileNum</code>和<code>formerLastTileLength</code>，计算如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">uint32_t</span><span class="w"> </span><span class="n">offset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">tiling</span><span class="p">.</span><span class="n">formerLength</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">;</span>
<span class="n">InitGm</span><span class="p">(</span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">offset</span><span class="p">,</span><span class="w"> </span><span class="n">tiling</span><span class="p">.</span><span class="n">formerLength</span><span class="p">);</span>
</code></pre></div><p>尾核使用<code>tailLength</code>和<code>tailTileNum</code>，且尾核内只包含主块，因此<code>lastTileLength</code>设置为0。尾核的Global Memory偏移需要在全部整核数据之后继续计算，代码如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">uint32_t</span><span class="w"> </span><span class="n">offset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">tiling</span><span class="p">.</span><span class="n">formerLength</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">tiling</span><span class="p">.</span><span class="n">formerNum</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">tiling</span><span class="p">.</span><span class="n">tailLength</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="p">(</span><span class="n">blockIdx</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="n">tiling</span><span class="p">.</span><span class="n">formerNum</span><span class="p">);</span>
<span class="n">InitGm</span><span class="p">(</span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">offset</span><span class="p">,</span><span class="w"> </span><span class="n">tiling</span><span class="p">.</span><span class="n">tailLength</span><span class="p">);</span>
</code></pre></div><p>完整的<code>Init</code>函数实现代码如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Init</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">z</span><span class="p">,</span>
<span class="w">                            </span><span class="n">MainTileWithTailCoreTiling</span><span class="w"> </span><span class="n">tiling</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">blockIdx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetBlockIdx</span><span class="p">();</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">blockIdx</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">tiling</span><span class="p">.</span><span class="n">formerNum</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">offset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">tiling</span><span class="p">.</span><span class="n">formerLength</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">;</span>
<span class="w">        </span><span class="n">InitGm</span><span class="p">(</span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">offset</span><span class="p">,</span><span class="w"> </span><span class="n">tiling</span><span class="p">.</span><span class="n">formerLength</span><span class="p">);</span>
<span class="w">        </span><span class="k">this</span><span class="o">-&gt;</span><span class="n">tileNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">tiling</span><span class="p">.</span><span class="n">formerTileNum</span><span class="p">;</span>
<span class="w">        </span><span class="k">this</span><span class="o">-&gt;</span><span class="n">lastTileLength</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">tiling</span><span class="p">.</span><span class="n">formerLastTileLength</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span><span class="w"> </span><span class="k">else</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">offset</span><span class="w"> </span><span class="o">=</span>
<span class="w">            </span><span class="n">tiling</span><span class="p">.</span><span class="n">formerLength</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">tiling</span><span class="p">.</span><span class="n">formerNum</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">tiling</span><span class="p">.</span><span class="n">tailLength</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="p">(</span><span class="n">blockIdx</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="n">tiling</span><span class="p">.</span><span class="n">formerNum</span><span class="p">);</span>
<span class="w">        </span><span class="n">InitGm</span><span class="p">(</span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">offset</span><span class="p">,</span><span class="w"> </span><span class="n">tiling</span><span class="p">.</span><span class="n">tailLength</span><span class="p">);</span>
<span class="w">        </span><span class="k">this</span><span class="o">-&gt;</span><span class="n">tileNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">tiling</span><span class="p">.</span><span class="n">tailTileNum</span><span class="p">;</span>
<span class="w">        </span><span class="k">this</span><span class="o">-&gt;</span><span class="n">lastTileLength</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0U</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>完成<code>Init</code>后，<code>Process</code>函数仍按照<code>tileNum</code>和<code>lastTileLength</code>进行循环处理。整核需要处理主块和尾块，尾核只处理主块；循环逻辑与<a href="tail_block_even_split.html">尾块均分</a>中的<code>Process</code>函数一致，此处不再展开。</p></article></div>`,1)])])}const w=a(e,[["render",t]]);export{m as __pageData,w as default};
